  },
  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00066",
          "explanation": "Doctor corrects the family's misconception that prior omeprazole non-response means current acid-suppression/protection therapy should be stopped, and that '胃CA' equals definitive inoperable or advanced cancer.",
          "quote": "不要再叠加奥美拉唑等同类抑酸药，也不要自行加止痛药。"
        },
        {
          "event_id": "lite_evt_00087",
          "explanation": "Doctor explicitly warns against treating '胃CA' as definitive and explains that staging requires further workup, addressing the family's cancer-certainty misunderstanding.",
          "quote": "“胃CA”常表示怀疑或诊断胃癌的简写，但单凭这几个字不能确认最终病理。"
        },
        {
          "event_id": "lite_evt_00114",
          "explanation": "Further correction: the doctor distinguishes '免疫组化' from TNM staging and clarifies that it does not alone determine operability or prognosis.",
          "quote": "免疫组化里的 CK、CDX2、Ki-67 等主要帮助判断肿瘤类型和增殖情况，不等同于 TNM 分期，也不能单凭这些加减号判断能否手术。"
        }
      ],
      "completion": "complete",
      "explanation": "The family repeatedly expresses belief that the biopsy result equals definitive cancer stage, that omeprazole non‑response invalidates all acid‑suppression drugs, and that surgery preparation implies guaranteed surgery. The doctor consistently corrects each misconception in plain language, distinguishes known from unknown facts, and checks family's understanding. Family teach‑back confirms corrected action (e.g., '病理一出来就尽快挂胃肠外科复诊，不能自己当成已经确定手术').",
      "ho_id": "HO1",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00066",
          "explanation": "Doctor explicitly surfaces the two stomach drugs, the prior omeprazole failure, and the hypertension medication uncertainty, then integrates them into a medication‑verification plan.",
          "quote": "艾司奥美拉唑镁肠溶片20mg，每日1次，早餐前约30分钟整片吞服；替普瑞酮胶囊50mg，每日3次，饭后服。不要再叠加奥美拉唑等同类抑酸药"
        },
        {
          "event_id": "lite_evt_00087",
          "explanation": "Doctor uses the family's vague recall about '胃CA' and '两周后营养门诊' to build a practical medication‑reconciliation and follow‑up map.",
          "quote": "明天优先联系原消化科病区或内镜中心，确认：是否取活检、病理何时出、谁负责通知；同时联系胃肠外科/住院处确认是否已转诊、床位及术前检查安排。"
        }
      ],
      "completion": "complete",
      "explanation": "The doctor actively elicited the two gastric medicines, discovered the prior omeprazole failure and hypertension uncertainty, and integrated them into a concrete, label‑based medication reconciliation plan with treating‑team confirmation. The family participated in teach‑back and adjustment.",
      "ho_id": "HO2",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00031",
          "explanation": "Doctor proposes using drug box/ bag photos to overcome discharge confusion and memory gaps, a low‑burden execution workaround.",
          "quote": "可把药盒正反面、药袋标签和出院记录拍清楚发来，我再帮您逐项核对服药时间。"
        },
        {
          "event_id": "lite_evt_00066",
          "explanation": "Doctor assigns concrete roles and materials: family writes call questions, photographs labels, and calls specific services, avoiding sole reliance on a generic follow‑up.",
          "quote": "明天优先联系原消化科病区或内镜中心，确认：是否取活检、病理何时出、谁负责通知；同时联系胃肠外科/住院处"
        }
      ],
      "completion": "complete",
      "explanation": "The doctor navigated the family's chaotic discharge, cost/transport barriers, and caregiver anxiety by giving feasible, low‑burden actions: photographing labels, preparing medication lists, and making targeted calls. The family acknowledged and executed the workaround (e.g., '我把明天要打电话的写纸上了').",
      "ho_id": "HO3",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00448",
          "explanation": "Doctor explicitly separates immediate safety, medication execution, follow‑up ownership, and unresolved staging/surgery questions in a teach‑back closure with family receipt.",
          "quote": "还没正式住院，是等外科床位电话，大概1到3个工作日；如果第3个工作日还没消息，我们就主动打外科或者住院处问。中间如果吐血、黑便、一直吐喝不进水、肚子硬、晕倒冒冷汗，或者喘得厉害、意识不对，就不等电话，直接急诊/120。"
        },
        {
          "event_id": "lite_evt_00333",
          "explanation": "Doctor distinguishes staged outpatient workup from transmission‑only handoff, preventing the family from treating this as terminal closure.",
          "quote": "不是病轻，而是现在要先把分期查清；没住院只是说明眼下没有必须急诊住院的出血、梗阻或不稳定表现，检查和复诊仍要抓紧。"
        }
      ],
      "completion": "complete",
      "explanation": "The doctor created a bounded closure that summarized completed decisions, classified residual risks (waiting for surgical bed, pathology, CT results), linked each to a responsible owner and time window, and obtained family teach‑back showing understanding that the conversation is a transition‑only step, not the end of cancer workup or perioperative management.",
      "ho_id": "HO4",
      "meaningful_trajectory_impact": true,
      "triggered": true
    }
  ],
